"""Rank-independent Star computation strategy; machine order is preserved."""

from __future__ import annotations

from typing import Protocol

from codegen.logical import StencilComputationSource, star_planes
from codegen.sass.dependency import DependencyManager
from codegen.sass.ir import InstrGroup, SASSOperation, StencilComputation
from codegen.state import CodeGenStatus


class Plane(Protocol):
    """Star lifecycle facts consumed by the shared computation strategy."""

    in_range: bool
    target_offset: int
    center_offset: int
    computation_sources: set[StencilComputationSource]

    def has_inter_thread_computation(self) -> bool: ...
    def __hash__(self) -> int: ...


class StarComputation:
    @staticmethod
    def insert_before(dst, src, pred):
        for i, item in enumerate(dst):
            if pred(item):
                dst[i:i] = src
                return

        dst.extend(src)

    def construct_planes(self, status: CodeGenStatus, time_step: int):
        planes = []

        for logical in star_planes(self.radius, status, time_step):
            regs = self.regs[time_step][
                type(self).wrap_add(
                    logical.index, status.runtime_offset, self.elements_per_time_step
                )
            ]

            if time_step == 0 and logical.target_offset == 0:
                slot = self.precomputed_addr_slot(logical.index)
                if slot is not None:
                    regs = slot

            regs = self.replacements.get(self.replacement_key(regs), regs)

            planes.append(
                self.plane_type(
                    time_step=time_step,
                    index=logical.index,
                    center_offset=logical.center_offset,
                    target_offset=logical.target_offset,
                    in_range=logical.in_range,
                    finishes_current_iteration=logical.finishes_current_iteration,
                    computation_sources=set(logical.computation_sources),
                    regs=regs,
                )
            )

        return planes

    def gen_indep_intra_comp(self, planes: list[Plane]) -> list[StencilComputation]:
        """
        This function generates all completely independent intra-thread computation instructions.
        These instructions can be issued in any order at any time within the current time step.

        Intra-thread computations typically contribute from the last plane (i.e., `planes[-1]`,
        which has a `target_offset` of 0) to the remaining planes, and also include self-updates
        from `planes[-2]` to itself. The latter have already been generated in
        `gen_smem_indep_inter_comp_self_update()`, so they are not repeated here.

        For the remaining computations, all computations are completely independent except for those
        that contribute to the following planes:

        - Computations that contribute to `planes[-2]`, as they can only be issued after the
          self-update of `planes[-2]` is completed.
        - Computations that contribute to `planes[self.radius - 1]`, as inter-thread computations
          also contribute to this plane, so dependencies must be established among all these
          computations.

        Additionally, we use the following heuristic strategies to schedule the instructions
        generated by this function:

        - Computation instructions that use the same register as a source operand should be issued
          consecutively to utilize `.reuse`.
        - Computation instructions that contribute to `planes[0]` should be issued as early as
          possible, as the values produced by this plane are needed in subsequent time steps.
        """

        # This variable stores the computation instructions generated for each `Plane` in the order
        # of their `index` values from low to high.
        plane_results: dict[Plane, list[StencilComputation]] = {}

        for dst_plane in planes[:-1]:
            # Skip `planes[-2]` and `planes[self.radius - 1]`, as they have dependencies on other
            # computations.
            if dst_plane.target_offset == -1 or dst_plane.center_offset == -1:
                continue

            if StencilComputationSource.SameColumn not in dst_plane.computation_sources:
                continue

            plane_results[dst_plane] = self.gen_intra_thread_computation(planes[-1], dst_plane)

        # The final results.
        results: list[StencilComputation] = []

        # Put the computation instructions that contribute to `planes[0]` at the front.
        if planes[0] in plane_results:
            results.extend(plane_results[planes[0]])
            plane_results.pop(planes[0])

        # Transpose `plane_results[1:]` and add them to `results`, because each sublist in
        # `plane_results` corresponds to a destination plane, and each computation instruction
        # contributes to one register in that plane. We group the computations with the same index
        # together, so that their source operands are all the same register in the same plane.
        results.extend(op for op_list in plane_results.values() for op in op_list)

        return results

    def gen_dep_intra_comp(self, planes: list[Plane]) -> list[StencilComputation]:
        """
        This function generates all intra-thread computation instructions that contribute to
        `planes[-2]` and `planes[self.radius - 1]`.
        """

        plane_results: list[list[StencilComputation]] = []

        for plane in (planes[-2], planes[self.radius - 1]):
            if StencilComputationSource.SameColumn in plane.computation_sources:
                plane_results.append(self.gen_intra_thread_computation(planes[-1], plane))

        # Interleave the computation instructions that contribute to `planes[-2]` and
        # `planes[self.radius - 1]`, so that the instructions that share the same source registers
        # are issued consecutively, which can utilize `.reuse`.
        return [op for op_list in zip(*plane_results, strict=False) for op in op_list]

    def gen_smem_comp_operations(
        self, planes: list[Plane], dep_manager: DependencyManager
    ) -> list[InstrGroup]:
        """
        This function generates all required shared-memory load/store and computation instructions
        for a given set of planes. It returns the generated instructions as a list of `InstrGroup`.
        Each group is led by at most `self.leading_load_count` shared-memory load instructions,
        along with generated computation instructions.
        """

        operations: list[SASSOperation] = []

        # `inter_comp_src_plane` is the plane that provides source operands for inter-thread
        # computations.
        #
        # This is because in each iteration, the source value of `planes[-1]` is written to shared
        # memory, and in the next iteration, its value is read back for inter-thread computations.
        # Therefore, the value read from shared memory is equivalent to the source operands of
        # `planes[-2]`.
        inter_comp_src_plane = planes[-2]

        # `inter_comp_dst_plane` is the plane that collects the results of neighbor planes from
        # other columns, so it is the target of all inter-thread computations for star stencils.
        inter_comp_dst_plane = planes[self.radius - 1]
        assert inter_comp_dst_plane.center_offset == -1

        # Step 1: Generate computation instructions for inter-thread computations that depend on
        # registers from other columns within the same thread. When a source operand is no longer
        # used, also initiate its self-update computation instruction.
        if inter_comp_dst_plane.has_inter_thread_computation():
            operations.extend(
                self.gen_smem_indep_inter_comp_self_update(
                    inter_comp_src_plane, inter_comp_dst_plane
                )
            )

        # Step 2: Generate intra-thread computation instructions that depend on the results of the
        # above inter-thread computation instructions. Since these computation instructions depend
        # on the previously generated inter-thread computation instructions, they must be issued
        # after the latter.
        operations.extend(self.gen_dep_intra_comp(planes))

        # Step 3: Generate all intra-thread computation instructions that are completely independent
        # of the above instructions. These instructions can be issued at any time, so we can use
        # them to fill the gaps in the above instructions.
        indep_intra_comp_instrs = self.gen_indep_intra_comp(planes)

        # Step 4: Interleave the independent intra-thread computation instructions into the above
        # instructions to fill the scheduling gaps.
        operations, indep_intra_comp_instrs = self.interleave_independent_instructions(
            operations, indep_intra_comp_instrs
        )

        # Step 5: Generate all inter-thread computation instructions that depend on neighbor values
        # loaded from shared memory, along with the corresponding LDS instructions.
        #
        # This step also reorganizes the instruction sequence into groups, where each group is led
        # by at most `self.leading_load_count` LDS instructions, and the computation instructions in
        # each group are evenly distributed.
        if inter_comp_dst_plane.has_inter_thread_computation():
            # Traverse the elements in `[-radius, 0)` and `[group_size, group_size + radius)`, which
            # are owned by other threads and published to shared memory.
            smem_dep_instr_groups = self.gen_smem_dep_inter_comps(
                inter_comp_src_plane, inter_comp_dst_plane
            )
            grouped_operations = self.interleave_smem_dep_instructions(
                operations, smem_dep_instr_groups, dep_manager
            )
        else:
            # If there are no inter-thread computations, then we do not need to generate any
            # shared-memory load instructions.
            #
            # We still need to convert `operations` into a nested structure to maintain consistency
            # with the return value of `interleave_smem_dep_instructions()`.
            grouped_operations = [InstrGroup(comp_instrs=operations)]

        # Step 6: Insert the remaining independent intra-thread computation instructions into each
        # group.
        grouped_operations = self.distribute_independent_instructions(
            grouped_operations, indep_intra_comp_instrs
        )

        # Step 7: Insert the shared-memory store instruction for `planes[-1]`.
        if planes[-1].in_range:
            grouped_operations = self.gen_and_distribute_smem_stores(planes[-1], grouped_operations)

        return grouped_operations

    def interleave_independent_instructions(
        self, target_ops: list[SASSOperation], indep_ops: list[SASSOperation]
    ) -> tuple[list[SASSOperation], list[SASSOperation]]:
        """
        This function fills the gaps in `target_ops` with independent instructions from `indep_ops`.
        It returns a tuple where the first element is the filled `target_ops`, and the second
        element is the remaining `indep_ops`.

        The function takes independent instructions from `indep_ops` in order until the gaps are
        filled or the independent instructions are exhausted. It ensures that the latency between
        adjacent instructions in the filled sequence is not less than `self.min_comp_stall`. For
        example, if `self.min_comp_stall` is 2 and a certain instruction has a stall cycle of 3, no
        new instruction will be inserted, as this would reduce the latency of that instruction to 1.
        """

        # Create a temporary `DependencyManager` instance to compute the minimum stall cycles for
        # each instruction.
        dep_manager = DependencyManager()
        dep_manager.add_dependencies(target_ops, self.stall_dict)
        dep_manager.compute_min_stalls(target_ops, per_op_min_stall=self.min_comp_stall)

        results: list[SASSOperation] = []
        # Record the position of the independent instruction to be inserted next.
        indep_op_pos = 0

        for target_op in target_ops:
            # Determine the number of instructions to be inserted.
            insert_count = min(
                target_op.stall // self.min_comp_stall - 1, len(indep_ops) - indep_op_pos
            )

            results.append(target_op)
            results.extend(indep_ops[indep_op_pos : indep_op_pos + insert_count])
            indep_op_pos += insert_count

            # We need to update the stall cycles of `operation` and the newly inserted instructions.
            # We want to evenly distribute `operation.stall` across all inserted instructions.
            avg_stall = target_op.stall // (insert_count + 1)
            for insert_op in indep_ops[indep_op_pos : indep_op_pos + insert_count]:
                insert_op.stall = avg_stall

            target_op.stall -= avg_stall * insert_count

        # Clear the stall cycles of each operation, as we will recalculate them later.
        for op in results:
            op.stall = 0

        return results, indep_ops[indep_op_pos:]

    def interleave_smem_dep_instructions(
        self,
        target_ops: list[SASSOperation],
        groups: list[InstrGroup],
        dep_manager: DependencyManager,
    ) -> list[InstrGroup]:
        """
        This function evenly interleaves the shared-memory load instructions and their dependent
        computation instructions from `groups` into `target_ops`. It divides the final instruction
        sequence into several `InstrGroup`s, where each group is led by at most
        `self.leading_load_count` shared-memory load instructions. The function aims to distribute
        the computation instructions in each group as evenly as possible. It also establishes the
        necessary scoreboard dependencies between the shared-memory load instructions and their
        dependent computation instructions, and stall dependencies between the shared-memory load
        instructions of adjacent groups through `dep_manager`.
        """

        # The total number of computation instructions.
        total_comp_count = len(target_ops) + sum(len(group.comp_instrs) for group in groups)
        # The number of computation instructions in each instruction group.
        avg_comp_count = total_comp_count // len(groups)

        # Records the computation instructions of the current group, which will be moved to the
        # front of the next group.
        current_computations: list[SASSOperation] = []

        for group_id, group in enumerate(groups):
            # Move the computation instructions in `group` to the front of the next group.
            current_computations, group.comp_instrs = group.comp_instrs, current_computations

            # Compute how many computation instructions we need to insert into this group.
            #
            # If we are processing the last group, we need to insert all remaining computation
            # instructions from `target_ops` into this group. Otherwise, we only insert enough
            # instructions to make it contain `avg_comp_count` computation instructions. Note that
            # `group` may already have some computation instructions (inserted by previous groups).
            insert_count = (
                len(target_ops)
                if group_id == len(groups) - 1
                else avg_comp_count - len(group.comp_instrs)
            )
            # Insert instructions from `target_ops` into `group`.
            group.comp_instrs.extend(target_ops[:insert_count])
            target_ops = target_ops[insert_count:]

        groups[-1].comp_instrs.extend(current_computations)

        dep_manager.connect_load_groups(groups)

        return groups
